/* atlas.js — #684 THE ATLAS: the drawn maps of a campaign, generated by the TnD Maps library (tndmaps.js).
   "The map" already means the location graph (memory.map), so the drawn maps are the atlas. Design: DOC/DESIGN_684_atlas.md.

   worldState.atlas = {v, seed, at, spot, off, ptr, zones, names}
     seed     the campaign's map seed — also the id of the root zone, the region
     zones    {<zoneId>: {kind, parent, via, params, name, lib, fp, turn, redrawn?}} — RECIPES, never documents. A zone's
              document is a pure function of its recipe chain; a region document is 303 KB and a city 134 KB, a recipe is
              bytes. A zone id is the seed the library derives for that zone (<seed>/p0, <seed>/p0/inn-1, <seed>/p0/sewer):
              unique by construction, the same from every way in. kind = the generator; via = what the parent's nesting
              function takes (a portal id; a wild zone's own id); params = authored params only — the root keeps its
              RESOLVED params, so a changed library default cannot redraw a running campaign's realm.
     at/spot  where the party stands: a zone id, and the id of a thing in it (null = somewhere in that zone). at null = the
              party has no place on the map yet.
     off      {name, why, within?} while the story's current place has no place on the map; at/spot keep the last mapped one
     ptr      the location pointer last followed (following is idempotent)
     names    {<location key>: {zone, id}} — a story place tied to a map thing

   THE RULE: the engine never guesses a tie. A story place is on the map when its name IS a map name (exact once case, a
   leading "the" and punctuation are folded, and only when one thing bears it), or when the player said so (atlasPlace —
   the pane's "We are here"). Anything else is off the map, said plainly; a guessed tie would be served to the GM as canon.

   Reads (atlasDoc, atlasThings, atlasPartyIn, atlasMarkers, atlasZones) never write the campaign. The writers are
   atlasCreate, atlasFollow, atlasPlace and atlasHeal; a redraw a read notices is recorded by the next writer. */
var ATLAS_VER=1;
/* documents held in memory at once: the least recently used is dropped and redrawn on demand (a region is ~300 KB) */
var ATLAS_DOC_CAP=12;

/* THE NESTING TABLE — "<parent generator>><child generator>": how the child's params come from the parent's document.
   via "id" = the portal's own id; "to" = the id the portal points at (a wild zone is named by its zone id). point = where
   the child sits on the parent's sheet when no thing of the parent bears the via. A new scale is a new entry. */
var ATLAS_BUILDERS={
  "region>town":{via:"id",make:function(doc,via){return TnDMaps.town.fromRegion(doc,via);}},
  "region>dungeon":{via:"id",make:function(doc,via){return TnDMaps.dungeon.fromRegion(doc,via);}},
  "region>wild":{via:"to",make:function(doc,via){return TnDMaps.wild.fromRegion(doc,via);},point:function(doc,via){var z=TnDMaps.wild.zoneAt(doc,via);return [z.cx,z.cy];}},
  "town>dungeon":{via:"id",make:function(doc,via){return TnDMaps.dungeon.fromTown(doc,via);}},
  "town>interior":{via:"id",make:function(doc,via){return TnDMaps.interior.fromTown(doc,via);}},
  "dungeon>dungeon":{via:"id",make:function(doc,via){return TnDMaps.dungeon.fromDungeon(doc,via);}},
  "interior>dungeon":{via:"id",make:function(doc,via){return TnDMaps.dungeon.fromInterior(doc,via);}}
};
/* the NAMED THINGS of a document, per generator, beside its portals (which every document carries) */
var ATLAS_THINGS={
  region:function(d){return [].concat(d.places||[],d.caves||[],d.features||[]);},
  town:function(d){return [].concat(d.establishments||[],d.landmarks||[]);},
  dungeon:function(d){return d.rooms||[];},
  interior:function(d){return d.rooms||[];},
  wild:function(d){return d.features||[];}
};
/* a portal of one of these ways leads back to the zone this one hangs from */
var ATLAS_WAYS_BACK={up:1,out:1};
/* v → the function lifting a store to v+1 (none yet: v1 is the first shape) */
var ATLAS_MIGRATIONS={};

var _atlasDocs={},_atlasDocOrder=[],_atlasDrawn={},_atlasWarned={};

function atlasSay(level,msg){
  if(typeof console!=="undefined")(console[level]||console.log).call(console,"[atlas] "+msg);
  if(level!=="info"&&typeof showToast==="function")showToast("Map: "+msg,6000);
}
/* an exception the atlas did not expect: loud, attributable, and never allowed out of a writer (a turn must still commit) */
function atlasProblem(where,e){
  var msg=(e&&e.message)?e.message:String(e);
  atlasSay("warn",where+" failed — "+msg);
  if(typeof reportError==="function"&&!/^TnDMaps: /.test(msg))reportError("atlas "+where,msg,(e&&e.stack)?String(e.stack).slice(0,600):"");
  return msg;
}
function atlasTurn(){return (typeof worldState!=="undefined"&&worldState&&typeof worldState.turn==="number")?worldState.turn:0;}
/* the store, when this build can use it; a store from a newer build is left alone, said once */
function atlasLive(){
  var A=(typeof worldState!=="undefined"&&worldState)?worldState.atlas:null;
  if(!A)return null;
  if(A.v!==ATLAS_VER){if(!_atlasWarned.ver){_atlasWarned.ver=1;atlasSay("warn","this campaign's map was saved by a newer version of the game (atlas v"+A.v+", this build reads v"+ATLAS_VER+") — it is left untouched");}return null;}
  return A;
}
function atlasHas(){return !!atlasLive();}
function atlasSeedMint(){
  var a="abcdefghijklmnopqrstuvwxyz0123456789",s="",i,r;
  if(typeof crypto!=="undefined"&&crypto&&crypto.getRandomValues){r=new Uint8Array(12);crypto.getRandomValues(r);for(i=0;i<12;i++)s+=a.charAt(r[i]%36);}
  else for(i=0;i<12;i++)s+=a.charAt(Math.floor(Math.random()*36));
  return s;
}
/* what the library drew, as one short string: the document without its timings (stats) and without the caches the
   library hangs on a document it has read (keys starting "_") — both differ between two draws of the same map */
function atlasFingerprint(doc){
  var s=JSON.stringify(doc,function(k,v){return (this===doc&&(k==="stats"||k.charAt(0)==="_"))?undefined:v;});
  return (TnDMaps.hash32(s)>>>0).toString(16)+"-"+s.length.toString(36);
}
function atlasNameKey(s){
  return String(s==null?"":s).toLowerCase().replace(/[‘’]/g,"'").replace(/[\s.,;:!?\-–—_"()\[\]]+/g," ").replace(/^ +| +$/g,"").replace(/^the /,"");
}

/* ── documents ─────────────────────────────────────────────────────────────────────────────────────────────── */
function atlasRecipe(A,zoneId){var rec=A.zones[zoneId];if(!rec)throw new Error("atlas: no zone '"+zoneId+"' in this campaign's atlas");return rec;}
/* a document is keyed by its whole recipe chain, so an authored change anywhere above can never serve a stale drawing */
function atlasChainKey(A,zoneId){
  var parts=[],z=zoneId,rec,guard=0;
  while(z){if(guard++>64)throw new Error("atlas: the zone chain above '"+zoneId+"' loops");rec=atlasRecipe(A,z);parts.push(z+"|"+rec.kind+"|"+(rec.via==null?"":rec.via)+"|"+(rec.params?JSON.stringify(rec.params):""));z=rec.parent;}
  return parts.join("\n");
}
function atlasZoneParams(A,zoneId){
  var rec=atlasRecipe(A,zoneId),params,b;
  if(!rec.parent)params=JSON.parse(JSON.stringify(rec.params));
  else{
    b=ATLAS_BUILDERS[atlasRecipe(A,rec.parent).kind+">"+rec.kind];
    if(!b)throw new Error("atlas: nothing builds a "+rec.kind+" from a "+atlasRecipe(A,rec.parent).kind+" (zone '"+zoneId+"')");
    params=b.make(atlasDoc(rec.parent),rec.via);
    if(rec.params)params=Object.assign({},params,JSON.parse(JSON.stringify(rec.params)));
  }
  if(!params||params.seed!==zoneId)throw new Error("atlas: zone '"+zoneId+"' now derives the seed '"+(params&&params.seed)+"' — the library names its zones differently than when this campaign was mapped");
  return params;
}
function atlasDoc(zoneId){
  var A=atlasLive();if(!A)throw new Error("atlas: this campaign has no atlas");
  var key=atlasChainKey(A,zoneId),doc=_atlasDocs[key],at;
  if(!doc){
    doc=TnDMaps.generate(atlasRecipe(A,zoneId).kind,atlasZoneParams(A,zoneId));
    _atlasDocs[key]=doc;_atlasDrawn[key]={fp:atlasFingerprint(doc),lib:TnDMaps.VERSION,name:(doc.title&&doc.title.name)||null};
  }else{at=_atlasDocOrder.indexOf(key);if(at>=0)_atlasDocOrder.splice(at,1);}
  _atlasDocOrder.push(key);
  while(_atlasDocOrder.length>ATLAS_DOC_CAP){at=_atlasDocOrder.shift();delete _atlasDocs[at];delete _atlasDrawn[at];}
  return doc;
}
/* drop every held document (a campaign switch, a test): the next read redraws from the recipes */
function atlasForget(){_atlasDocs={};_atlasDocOrder=[];_atlasDrawn={};_atlasWarned={};}
/* WRITE: record what the library drew for a zone; a drawing that differs from the one on record is said out loud */
function atlasSettle(A,zoneId){
  var rec=A.zones[zoneId],d=rec?_atlasDrawn[atlasChainKey(A,zoneId)]:null;
  if(!d)return null;
  if(d.name&&rec.name!==d.name)rec.name=d.name;
  if(!rec.fp){rec.fp=d.fp;rec.lib=d.lib;return null;}
  if(rec.fp===d.fp){if(rec.lib!==d.lib)rec.lib=d.lib;return null;}
  rec.redrawn={from:rec.lib,to:d.lib,was:rec.fp,turn:atlasTurn()};rec.fp=d.fp;rec.lib=d.lib;
  atlasSay("warn","the map of "+(rec.name||zoneId)+" was redrawn"+(rec.redrawn.from!==rec.redrawn.to?" by a newer map library ("+rec.redrawn.from+" → "+rec.redrawn.to+")":" differently from its record")+" — places the story already used there may have moved");
  return rec.redrawn;
}
function atlasSettleChain(A,zoneId){var z=zoneId,guard=0;while(z&&A.zones[z]&&guard++<64){atlasSettle(A,z);z=A.zones[z].parent;}}

/* ── things: what on a sheet has a name ────────────────────────────────────────────────────────────────────── */
function atlasThings(doc){
  var kind=doc.generator&&doc.generator.name,list=ATLAS_THINGS[kind]?ATLAS_THINGS[kind](doc):[],out=[],byId={},i,j,keep;
  function add(o,portal){
    if(!o||o.id==null||typeof o.name!=="string"||!o.name||!isFinite(o.x)||!isFinite(o.y))return;
    if(byId[o.id]){if(portal&&!byId[o.id].portal)byId[o.id].portal=portal;return;}
    byId[o.id]={id:o.id,name:o.name,x:o.x,y:o.y,kind:o.kind||null,word:o.word||null,portal:portal||null};out.push(byId[o.id]);
  }
  for(i=0;i<(doc.portals||[]).length;i++)add(doc.portals[i],doc.portals[i]);
  for(i=0;i<list.length;i++)add(list[i],null);
  /* one place under two ids (a town's outfall is a landmark and a way down at one point): the way in is the thing */
  keep=out.filter(function(t){
    if(t.portal)return true;
    for(j=0;j<out.length;j++)if(out[j].portal&&atlasNameKey(out[j].name)===atlasNameKey(t.name)&&Math.abs(out[j].x-t.x)<=2&&Math.abs(out[j].y-t.y)<=2)return false;
    return true;
  });
  return keep;
}
function atlasThingById(doc,id){var t=atlasThings(doc),i;for(i=0;i<t.length;i++)if(t[i].id===id)return t[i];return null;}
/* a name on one sheet: {thing} when exactly one thing bears it, {many: n} when several do, {title: true} for the sheet's own name */
function atlasFind(doc,name){
  var key=atlasNameKey(name),hits;
  if(!key)return null;
  hits=atlasThings(doc).filter(function(t){return atlasNameKey(t.name)===key;});
  if(hits.length===1)return {thing:hits[0]};
  if(hits.length>1)return {many:hits.length};
  if(doc.title&&atlasNameKey(doc.title.name)===key)return {title:true};
  return null;
}
function atlasCentre(doc){
  var c=doc.centre;
  if(c&&isFinite(c[0])&&isFinite(c[1]))return [c[0],c[1]];
  return [doc.frame.width/2,doc.frame.height/2];
}

/* ── moving between zones ──────────────────────────────────────────────────────────────────────────────────── */
/* where a way in comes out on the far side: the thing with the same id, else the ONE portal that points back at it —
   a town has several roads onto its place and a house two doors, and which one the party used is not on record */
function atlasWayIn(doc,from){
  var i,p,back=[];
  if(from==null)return null;
  if(atlasThingById(doc,from))return from;
  for(i=0;i<(doc.portals||[]).length;i++){p=doc.portals[i];if(p.to&&p.to.id===from)back.push(p.id);}
  return back.length===1?back[0]:null;
}
/* WRITE: the zone a builder makes from parentZone — its recipe is filed the first time, then it is the same zone from every way in */
function atlasOpen(A,parentZone,kind,via,from,entered){
  var b=ATLAS_BUILDERS[atlasRecipe(A,parentZone).kind+">"+kind],params=b.make(atlasDoc(parentZone),via),id=params&&params.seed,fresh=false,doc;
  if(typeof id!=="string"||!id)throw new Error("atlas: the library derived no seed for a "+kind+" through '"+via+"'");
  if(!A.zones[id]){A.zones[id]={kind:kind,parent:parentZone,via:via,params:null,name:null,lib:null,fp:null,turn:atlasTurn()};fresh=true;}
  try{doc=atlasDoc(id);}catch(e){if(fresh)delete A.zones[id];throw e;}
  if(fresh){atlasSettle(A,id);if(entered)entered.push(id);atlasSay("info","drew "+(A.zones[id].name||id)+" ("+kind+")");}
  return {zone:id,spot:atlasWayIn(doc,from)};
}
/* the zone a portal leads to, opened if it is new; null when it leads nowhere (the edge of the realm) */
function atlasPortalTarget(A,zoneId,portal,entered){
  var G=portal.to&&portal.to.generator,z,b,via;
  if(!G)return null;
  if(ATLAS_WAYS_BACK[portal.way]){z=atlasRecipe(A,zoneId).parent;return z?{zone:z,spot:atlasWayIn(atlasDoc(z),portal.to.id)}:null;}
  /* the nearest zone, from here upward, that can build a G: a wild zone's ways lead to zones that hang from the region */
  for(z=zoneId;z;z=atlasRecipe(A,z).parent){
    b=ATLAS_BUILDERS[atlasRecipe(A,z).kind+">"+G];
    if(b){via=(b.via==="to")?portal.to.id:portal.id;return via==null?null:atlasOpen(A,z,G,via,portal.id,entered);}
  }
  /* nothing builds one: it is a way back up to the zone of that kind (a town's road onto the region) */
  for(z=atlasRecipe(A,zoneId).parent;z;z=atlasRecipe(A,z).parent)if(atlasRecipe(A,z).kind===G)return {zone:z,spot:atlasWayIn(atlasDoc(z),portal.to.id)};
  return null;
}
/* standing at a thing: a way in is entered, anything else is a spot on its own sheet */
function atlasArrive(A,zone,id,entered){
  var t,target;
  if(id==null)return {zone:zone,spot:null};
  t=atlasThingById(atlasDoc(zone),id);
  if(!t)throw new Error("atlas: '"+id+"' is not on the map of "+(atlasRecipe(A,zone).name||zone)+" any more");
  if(t.portal&&!ATLAS_WAYS_BACK[t.portal.way]){target=atlasPortalTarget(A,zone,t.portal,entered);if(target)return target;}
  return {zone:zone,spot:id};
}

/* ── the location pointer ──────────────────────────────────────────────────────────────────────────────────── */
function atlasPointer(){var w=(typeof worldState!=="undefined"&&worldState)?worldState.world:null;return (w&&w.location)?{world:String(w.location),sub:w.sublocation?String(w.sublocation):null}:null;}
function atlasLocKey(k){return (typeof locResolve==="function")?locResolve(k):k;}
function atlasWorldKey(p){return atlasLocKey(p.world);}
function atlasSubKey(p){return p.sub?atlasLocKey(atlasWorldKey(p)+"|"+p.sub):null;}
/* search scopes, nearest first: a world name looks from where the party stands up to the region; a sub-location looks
   on the sheet the world name led to, then on the sheets already entered beneath it */
function atlasScopeUp(A,zoneId){var out=[],z=zoneId,guard=0;while(z&&A.zones[z]&&guard++<64){out.push([z]);z=A.zones[z].parent;}return out;}
function atlasScopeDown(A,zoneId){
  var out=[[zoneId]],level=[zoneId],ids=Object.keys(A.zones),next,guard=0;
  while(level.length&&guard++<64){
    next=ids.filter(function(id){return level.indexOf(A.zones[id].parent)>=0;});
    if(next.length)out.push(next);
    level=next;
  }
  return out;
}
/* a story name → {hit: {zone, id}} or {hit: null, why}. A recorded tie wins; otherwise the first scope level where the
   name is found decides, and it must be found exactly once there — two bearers is a refusal, never a pick. */
function atlasResolve(A,key,name,scope){
  var tie=A.names[key],i,j,found,m,title;
  if(tie&&A.zones[tie.zone])return {hit:{zone:tie.zone,id:tie.id==null?null:tie.id}};
  for(i=0;i<scope.length;i++){
    found=[];
    for(j=0;j<scope[i].length;j++){
      m=atlasFind(atlasDoc(scope[i][j]),name);
      if(!m)continue;
      title=A.zones[scope[i][j]].name||scope[i][j];
      if(m.many)return {hit:null,why:m.many+" places on the map of "+title+" are called that"};
      found.push({zone:scope[i][j],id:m.thing?m.thing.id:null});
    }
    if(found.length>1)return {hit:null,why:found.length+" mapped places are called that"};
    if(found.length===1){A.names[key]=found[0];return {hit:found[0]};}
  }
  return {hit:null,why:"no place on the map has that name"};
}
/* WRITE: follow the story's location pointer. Idempotent; never throws (it runs inside a turn's commit). Returns
   {changed, at, spot, off, entered} or null when the campaign has no atlas. */
function atlasFollow(){
  var A=atlasLive(),p=A?atlasPointer():null,sig,before,entered=[],w,s;
  if(!A||!p)return null;
  sig=JSON.stringify([p.world,p.sub]);
  if(A.ptr===sig){try{atlasSettleChain(A,A.at);}catch(e0){atlasProblem("settling",e0);}return {changed:false,at:A.at,spot:A.spot,off:A.off,entered:entered};}
  before=JSON.stringify([A.at,A.spot,A.off]);
  try{
    w=atlasResolve(A,atlasWorldKey(p),p.world,atlasScopeUp(A,A.at||A.seed));
    if(!w.hit)A.off={name:p.world,why:w.why};
    else{
      atlasStand(A,atlasArrive(A,w.hit.zone,w.hit.id,entered));A.off=null;
      if(p.sub){
        s=atlasResolve(A,atlasSubKey(p),p.sub,atlasScopeDown(A,A.at));
        if(s.hit)atlasStand(A,atlasArrive(A,s.hit.zone,s.hit.id,entered));
        else A.off={name:p.sub,why:s.why,within:A.at};
      }
    }
    atlasSettleChain(A,A.at);
  }catch(e){A.off={name:p.sub||p.world,why:"the map could not follow the story there ("+atlasProblem("following the party",e)+")"};}
  A.ptr=sig;
  return {changed:before!==JSON.stringify([A.at,A.spot,A.off]),at:A.at,spot:A.spot,off:A.off,entered:entered};
}
function atlasStand(A,where){A.at=where.zone;A.spot=where.spot==null?null:where.spot;}

/* WRITE: start a campaign's atlas — the region is drawn now, the party is not on it yet. Throws on a second call. */
function atlasCreate(seed){
  var A,doc;
  if(typeof worldState==="undefined"||!worldState)throw new Error("atlas: no campaign is loaded");
  if(worldState.atlas)throw new Error("atlas: this campaign already has an atlas");
  if(seed==null)seed=atlasSeedMint();
  if(typeof seed!=="string"||!/^[A-Za-z0-9-]{4,40}$/.test(seed))throw new Error("atlas: a map seed is 4–40 letters, digits or hyphens");
  doc=TnDMaps.generate("region",{seed:seed});
  A={v:ATLAS_VER,seed:seed,at:null,spot:null,off:null,ptr:null,zones:keyedDict(),names:keyedDict()};
  A.zones[seed]={kind:"region",parent:null,via:null,params:JSON.parse(JSON.stringify(doc.params)),name:(doc.title&&doc.title.name)||null,lib:TnDMaps.VERSION,fp:atlasFingerprint(doc),turn:atlasTurn()};
  worldState.atlas=A;
  atlasSay("info","drew "+A.zones[seed].name+" (region) from the seed "+seed);
  return A;
}

/* WRITE: "We are here" — the player ties the story's current place to a thing on a sheet ({id}), or to open ground on
   the region ({x, y}: the wild zone at that point). The WORLD place is tied first: with a sub-location in the pointer
   and the world place not yet on the map, the tap places the world (a tavern cannot stand in a town the map does not
   know); once the world is tied, the tap places the sub-location. level ("world" | "sub") overrides that choice.
   Returns {ok: true, at, spot, off, entered, bound, level} or {ok: false, reason}; a refusal changes nothing but
   zones the tap had to draw to look. */
function atlasPlace(zoneId,target,level){
  var A=atlasLive(),p=A?atlasPointer():null,entered=[],rec,doc,tie,b,z,r,msg,wTie;
  if(!A)return {ok:false,reason:"this campaign has no map"};
  if(!p)return {ok:false,reason:"the story has no current place"};
  if(!A.zones[zoneId])return {ok:false,reason:"that sheet is not in this campaign's atlas"};
  if(level!=null&&level!=="world"&&level!=="sub")return {ok:false,reason:"a place is tied at the world or the sub level"};
  if(level==="sub"&&!p.sub)return {ok:false,reason:"the story names no sub-location to place"};
  try{
    rec=A.zones[zoneId];doc=atlasDoc(zoneId);
    if(target&&target.id!=null){
      if(!atlasThingById(doc,target.id))return {ok:false,reason:"nothing on that sheet has the id '"+target.id+"'"};
      tie={zone:zoneId,id:target.id};atlasArrive(A,zoneId,target.id,entered);
    }else if(target&&isFinite(target.x)&&isFinite(target.y)){
      b=ATLAS_BUILDERS[rec.kind+">wild"];
      if(!b)return {ok:false,reason:"only the region has open country to stand in — pick a place on this sheet"};
      z=TnDMaps.wild.zoneAt(doc,[target.x,target.y]);
      tie={zone:atlasOpen(A,zoneId,"wild",z.id,null,entered).zone,id:null};
    }else return {ok:false,reason:"pick a place or a point on the sheet"};
  }catch(e){
    msg=(e&&e.message)?e.message:String(e);
    if(!/^TnDMaps: /.test(msg))atlasProblem("placing the party",e);
    return {ok:false,reason:msg.replace(/^TnDMaps: /,"").replace(/ — \{[\s\S]*$/,"")};
  }
  wTie=A.names[atlasWorldKey(p)];
  if(level==null)level=(p.sub&&wTie&&A.zones[wTie.zone])?"sub":"world";
  A.names[level==="sub"?atlasSubKey(p):atlasWorldKey(p)]=tie;A.ptr=null;
  r=atlasFollow();
  return {ok:true,at:A.at,spot:A.spot,off:A.off,entered:entered.concat((r&&r.entered)||[]),bound:level==="sub"?p.sub:p.world,level:level};
}

/* ── reads for the pane and the prompt ─────────────────────────────────────────────────────────────────────── */
/* where the party shows on a zone's sheet: on its own sheet at its spot, on a sheet above at the way down to it.
   exact false = the party is in that zone but the map does not know where. null = not on that sheet. */
function atlasPartyIn(zoneId){
  var A=atlasLive(),doc,t,z,rec,b,c,guard=0;
  if(!A||!A.at||!A.zones[zoneId]||!A.zones[A.at])return null;
  doc=atlasDoc(zoneId);
  if(A.at===zoneId){t=A.spot!=null?atlasThingById(doc,A.spot):null;if(t)return {x:t.x,y:t.y,exact:true,within:null};c=atlasCentre(doc);return {x:c[0],y:c[1],exact:false,within:null};}
  for(z=A.at;z&&A.zones[z]&&guard++<64;z=A.zones[z].parent){
    rec=A.zones[z];
    if(rec.parent!==zoneId)continue;
    t=atlasThingById(doc,rec.via);
    if(t)return {x:t.x,y:t.y,exact:true,within:z};
    b=ATLAS_BUILDERS[A.zones[zoneId].kind+">"+rec.kind];
    if(b&&b.point){c=b.point(doc,rec.via);return {x:c[0],y:c[1],exact:true,within:z};}
    c=atlasCentre(doc);return {x:c[0],y:c[1],exact:false,within:z};
  }
  return null;
}
/* the markers TnDMaps.markers / view.setMarkers take for a sheet — derived from the store, never stored */
function atlasMarkers(zoneId){var p=atlasPartyIn(zoneId);return p?[{id:"party",kind:"party",x:p.x,y:p.y,label:"The party"}]:[];}
/* the entered zones, root first then in order of entry */
function atlasZones(){
  var A=atlasLive();if(!A)return [];
  return Object.keys(A.zones).map(function(id){var r=A.zones[id];return {id:id,kind:r.kind,name:r.name||id,parent:r.parent,turn:r.turn,redrawn:r.redrawn||null};});
}
/* the chain of zones from the region down to one zone */
function atlasTrail(zoneId){var A=atlasLive(),out=[],z=zoneId,guard=0;if(!A)return out;while(z&&A.zones[z]&&guard++<64){out.unshift(z);z=A.zones[z].parent;}return out;}

/* ── load ──────────────────────────────────────────────────────────────────────────────────────────────────── */
function atlasShapeProblem(A){
  var ids,i,r;
  if(!A||typeof A!=="object")return "it is not an object";
  if(typeof A.v!=="number")return "it has no version";
  if(A.v>ATLAS_VER)return null;/* a newer build's store: atlasLive leaves it alone */
  if(typeof A.seed!=="string"||!A.seed)return "it has no seed";
  if(!A.zones||typeof A.zones!=="object")return "it has no zones";
  if(!A.zones[A.seed]||A.zones[A.seed].kind!=="region"||A.zones[A.seed].parent||!A.zones[A.seed].params||A.zones[A.seed].params.seed!==A.seed)return "its region recipe is missing or does not carry the campaign seed";
  ids=Object.keys(A.zones);
  for(i=0;i<ids.length;i++){
    r=A.zones[ids[i]];
    if(!r||typeof r!=="object"||typeof r.kind!=="string")return "zone '"+ids[i]+"' is malformed";
    if(ids[i]!==A.seed&&(!r.parent||!A.zones[r.parent]))return "zone '"+ids[i]+"' hangs from a zone that is not there";
  }
  return null;
}
/* WRITE, at every load door: migrate the store's shape, set an unreadable store aside as evidence (never repaired by
   guessing, never silently dropped), drop ties and a position that point at zones that are gone. Returns true on a change. */
function atlasHeal(){
  var A=(typeof worldState!=="undefined"&&worldState)?worldState.atlas:null,why,changed=false,keys,i;
  if(A===undefined||A===null)return false;
  while(A&&typeof A==="object"&&typeof A.v==="number"&&A.v<ATLAS_VER){
    if(!ATLAS_MIGRATIONS[A.v]){worldState.atlasJunk={why:"no migration from atlas v"+A.v,was:A,turn:atlasTurn()};delete worldState.atlas;atlasSay("warn","this campaign's map is from an older shape this build cannot lift (v"+A.v+") — it was set aside");return true;}
    A=worldState.atlas=ATLAS_MIGRATIONS[A.v](A);changed=true;
  }
  why=atlasShapeProblem(A);
  if(why){worldState.atlasJunk={why:why,was:A,turn:atlasTurn()};delete worldState.atlas;atlasSay("warn","this campaign's map could not be read ("+why+") — it was set aside, the story is untouched");return true;}
  if(A.v>ATLAS_VER)return changed;
  if(!A.names||typeof A.names!=="object"){A.names=keyedDict();changed=true;}
  keys=Object.keys(A.names);
  for(i=0;i<keys.length;i++)if(!A.names[keys[i]]||!A.zones[A.names[keys[i]].zone]){delete A.names[keys[i]];changed=true;atlasSay("info","dropped the tie for '"+keys[i]+"' — its zone is not in the atlas");}
  if(A.at&&!A.zones[A.at]){A.at=null;A.spot=null;A.ptr=null;changed=true;atlasSay("warn","the party's place on the map pointed at a zone that is not there — the map will follow the story again");}
  return changed;
}
